            .overlay(shape.stroke(Color.black.opacity(0.16), lineWidth: 2).blur(radius: 1.5).offset(y: 1).mask(shape))
            .overlay(shape.stroke(Color.primary.opacity(0.10), lineWidth: 1))
    }
}

